// Clientes de un alimentador por S/E y nombre (mismo nombre en dos S/E: desempata la S/E; nombres viejos o cortados también sirven)
function clientesDe(se, nombre) {
  const sq = s => String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  const VIEJOS = { MANUELASAENZ: "MANUELITASAENZ", FERROVIARIO: "FERROVIARIA", SUBTERRANEO: "SUBTERRANEA", PASAP: "PASA", PILLAROCENTRO: "PILLARO",
    PILISURCO: "PILISHURCO", PITITIG: "PITITIC", LAPRADERA: "PRADERA", PISQUE: "ELPISQUE", PICAIGUA: "PICAIHUA", PALAHUA: "PALAGUA", CENTRALPUYO: "CENTRAL" };
  let n = sq(nombre); n = VIEJOS[n] || n;
  const s = sq(se);
  if (n.length < 3) return "";
  let c = CLIENTES.filter(r => sq(r[1]) === n);
  if (!c.length && n.length >= 5) c = CLIENTES.filter(r => sq(r[1]).startsWith(n) || n.startsWith(sq(r[1])));
  if (c.length > 1 && s) c = c.filter(r => sq(r[0]).startsWith(s) || s.startsWith(sq(r[0])));
  return c.length === 1 ? String(c[0][2]) : "";
}
